/* Informações públicas verificadas na loja. Nenhuma chamada à loja ou aos contatos é automática. */
function officialLink(url,text,cls='text-link'){return `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${text} ${icon('arrow')}</a>`;}
function officialLogo(cls='official-logo'){return `<img class="${cls}" src="${O.logo}" alt="Logotipo oficial do Empório Encantos da Serra">`;}
function officialProductThumb(p){return `<div class="product-icon official-thumb"><img src="${esc(p.image)}" alt="" loading="lazy"></div>`;}
function officialBanner(){return `<section class="official-banner"><div class="official-banner-brand">${officialLogo()}<div><span class="eyebrow">ENCANTOS DA SERRA</span><h2>Empório delivery</h2><p>Catálogo e identidade do site oficial. Pedidos, lotes e financeiro são simulações.</p></div></div><div class="actions"><a class="btn" href="#/empresa">Sobre a empresa</a><a class="btn primary" href="#/catalogo">Conhecer o catálogo ${icon('arrow')}</a></div></section>`;}
function officialCatalogPage(){let items=O.products.filter(p=>(catalogFilter==='todos'||(catalogFilter==='Sem lactose'?p.tags?.includes('Sem lactose'):p.category===catalogFilter))&&(!catalogSearch||(p.name+' '+p.category+' '+p.presentation).toLocaleLowerCase('pt-BR').includes(catalogSearch.toLocaleLowerCase('pt-BR'))));const groups=[...new Set(O.products.map(p=>p.category))];return pageHeading('O EMPÓRIO NA DEMONSTRAÇÃO','Iguarias com a cara da Canastra.','Seleção de produtos com fotos, nomes e preços consultados na loja oficial.',officialLink(O.site,'Abrir loja oficial','btn'))+`<div class="catalog-source-bar"><span class="badge green">${O.products.length} produtos verificados</span><span>Consulta em ${date(O.checkedAt)} · preços podem mudar na loja</span><a class="text-link" href="#/empresa">Ver informações e fontes ${icon('arrow')}</a></div><div class="catalog-toolbar"><label class="search">${icon('search')}<span class="screen-reader">Buscar no catálogo oficial</span><input id="catalog-search" placeholder="Buscar uma iguaria" value="${esc(catalogSearch)}"></label><label class="catalog-filter">Categoria<select id="catalog-category"><option value="todos">Todos os produtos</option>${[...groups,'Sem lactose'].map(c=>`<option ${catalogFilter===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><span class="micro">${items.length} produto${items.length===1?'':'s'} nesta seleção</span></div><div class="catalog-grid">${items.map(p=>`<article class="catalog-product"><button class="catalog-image" data-action="official-product" data-id="${p.id}" aria-label="Ver ${esc(p.name)}"><img src="${p.image}" alt="${esc(p.name)}" loading="lazy"></button><div class="catalog-product-body"><span class="catalog-category-name">${esc(p.category)}</span><h2><button data-action="official-product" data-id="${p.id}">${esc(p.name)}</button></h2><p class="catalog-presentation">${esc(p.presentation)}</p><div class="catalog-price">${p.previousPrice?`<del>${money(p.previousPrice)}</del>`:''}<strong>${money(p.price)}</strong><small>Preço publicado em ${short(O.checkedAt)}</small></div><div class="catalog-card-actions"><button class="text-link" data-action="official-product" data-id="${p.id}">Detalhes ${icon('arrow')}</button><button class="btn soft" data-action="request-product" data-id="${p.id}">Simular pedido</button></div></div></article>`).join('')||'<div class="empty catalog-empty">Nenhum produto nesta busca.<br>Experimente outro nome ou categoria.</div>'}</div><section class="official-categories"><h2>As categorias da loja</h2><p class="subtitle">Explore o catálogo completo no site da empresa.</p><div class="category-links">${O.categories.map(c=>officialLink(c.url,esc(c.name),'category-link')).join('')}</div></section><div class="note">Esta é uma seleção de ${O.products.length} produtos do catálogo, consultada em ${date(O.checkedAt)}. Frete, estoque real e disponibilidade dependem da loja. A solicitação neste protótipo fica no navegador e não gera uma compra.</div>`;}
function officialProductModal(id){const p=O.products.find(p=>p.id===id);if(!p)return;openModal(modalHead('CATÁLOGO DO SITE OFICIAL',esc(p.name))+`<div class="official-product-hero"><img src="${p.image}" alt="${esc(p.name)}"><div><span class="badge green">Informação publicada</span><p class="catalog-presentation">${esc(p.presentation)}</p><div class="catalog-price">${p.previousPrice?`<del>${money(p.previousPrice)}</del>`:''}<strong>${money(p.price)}</strong><small>Consulta em ${date(O.checkedAt)}</small></div></div></div><div class="modal-section"><h3>Sobre o produto</h3><p class="field-value">${esc(p.description)}</p>${p.producer!=='Não informado no site'?`<span class="field-label">Produção indicada na descrição</span><p class="field-value">${esc(p.producer)}</p>`:''}${p.sourceNote?`<div class="note amber">${esc(p.sourceNote)}</div>`:''}</div><div class="note">O preço vem da página do produto. Custos de compra, lotes, saldos e pedidos mostrados no ERP são exemplos acadêmicos.</div><div class="modal-footer">${officialLink(p.sourceUrl,'Ver página oficial','btn')}<button class="btn primary" data-action="request-product" data-id="${p.id}">Simular solicitação ${icon('arrow')}</button></div>`);}
function officialCompanyPage(){return pageHeading('A EMPRESA DO PROJETO','Encantos da Serra','Informações públicas da empresa, reunidas para o projeto acadêmico de Engenharia da Computação.',officialLink(O.site,'Visitar site oficial','btn primary'))+`<section class="company-hero"><div class="company-intro">${officialLogo('company-logo')}<div><span class="eyebrow">IDENTIDADE PUBLICADA NA LOJA</span><h2>Encantos da Serra<br><em>Empório delivery</em></h2><p>${esc(O.positioning)}</p><span class="company-date">Consulta às páginas públicas em ${date(O.checkedAt)}</span></div></div><div class="company-product-strip">${['p1','p4','p9'].map(id=>{const p=O.products.find(p=>p.id===id);return `<button data-action="official-product" data-id="${id}" aria-label="Ver ${esc(p.name)}"><img src="${p.image}" alt="${esc(p.name)}"></button>`;}).join('')}</div></section><div class="company-facts"><div><span class="field-label">O que o site anuncia</span><h3>Envio para todo o Brasil</h3><p>Entrega nacional anunciada na loja. Frete e atendimento por região precisam de consulta.</p></div><div><span class="field-label">Pagamento publicado</span><h3>Crédito ou à vista</h3><p>O site informa cartão de crédito e pagamento à vista. Fiado e Pix permanecem hipóteses da demonstração.</p></div><div><span class="field-label">Origem no catálogo</span><h3>Serra da Canastra</h3><p>A região aparece na apresentação e em descrições de produtos. Isso não define o endereço da empresa.</p></div></div><div class="company-grid"><section class="panel"><div class="panel-head"><div><h2>Canais publicados</h2><p class="subtitle">Os contatos abaixo são os que aparecem no site consultado.</p></div></div><div class="official-contact-list"><div><span>Telefone do site</span><a href="${O.phoneHref}">${O.phone}</a></div><div><span>Botão do WhatsApp</span>${officialLink(O.whatsappUrl,O.whatsapp)}</div><div><span>E-mail</span><a href="mailto:${O.email}">${O.email}</a></div><div><span>Instagram</span>${officialLink(O.instagramUrl,O.instagram)}</div></div><div class="contact-note">O cabeçalho e a página de contato exibem um número diferente do link de WhatsApp. Os dois foram preservados conforme publicados. A empresa precisa confirmar o canal preferencial.</div></section><section class="panel provenance-panel"><div class="panel-head"><h2>Dados oficiais e simulação</h2></div><div class="provenance-content"><h3>Informações verificadas na loja</h3><p>Nome, logotipo, categorias, fotos, preços da seleção e contatos. Cada produto tem acesso à sua página de origem.</p><h3>Operação acadêmica</h3><p>Clientes, pedidos, recebimentos, lotes, custos e capacidade não representam dados internos da empresa. As regras de fiado e personalizados vêm do escopo do projeto.</p><h3>Dados ainda não confirmados</h3><p>Endereço físico, horários, CNPJ, capacidade dos fornecedores e condições reais de atacado não constam nas páginas consultadas.</p></div></section></div><section class="official-categories"><h2>${O.categories.length} categorias no site</h2><div class="category-links">${O.categories.map(c=>officialLink(c.url,esc(c.name),'category-link')).join('')}</div></section><div class="note">Fontes: ${officialLink(O.site,'Página inicial')}, ${officialLink(O.contactPage,'Contato')} e páginas individuais acessíveis pelo catálogo. Os dados foram consultados em ${date(O.checkedAt)} e não são sincronizados automaticamente.</div>`;}
function officialSuppliersPage(){return pageHeading('PRODUÇÃO CITADA NOS PRODUTOS','A origem que o catálogo informa.','Marcas e produção identificadas nas descrições consultadas. Relações comerciais e capacidades precisam de validação.')+`<div class="producer-grid">${O.producers.map(p=>`<section class="producer"><div class="producer-top"><div class="avatar">${esc(initials(p.name))}</div><div><h3>${esc(p.name)}</h3><p class="subtitle">${esc(p.city)}</p></div></div><span class="badge green">Produção citada no site</span><p class="field-value">${esc(p.note)}</p><div class="details-grid"><div><span class="field-label">Capacidade mensal</span><div class="field-value">Não publicada</div></div><div><span class="field-label">Certificações</span><div class="field-value">Não informadas na página</div></div></div><div class="client-history">${officialLink(O.products.find(x=>x.id===p.productId).sourceUrl,'Conferir fonte')}</div></section>`).join('')}</div><div class="note amber">O site identifica a produção desses produtos. A confirmação dos fornecedores atuais, de suas capacidades e certificações pertence ao levantamento com a empresa. O cadastro e as ordens de compra continuam previstos no escopo do ERP.</div>`;}
